use super::*;
fn observe<T>(work:impl FnOnce()->T)->(T,usize,usize){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(work);(value,heap.requested_bytes,heap.released_bytes)}
fn decode<T:semio_framework_value::FromValue>(text:&str)->T{let mut receive=|_|true;let mut control=semio_framework_value::NativeDecodeControl::new(16*1024*1024,&mut receive);semio_framework_pack_json::from_json_str_controlled(text,semio_framework_pack_json::JsonMemberPolicy::Reject,&mut control).unwrap()}
#[derive(semio_framework_value::RetireOwned)]
struct Sources{tree:Tree,expected:HistoryFoldIndex<String,Dictionary>,output:Option<HistoryFoldIndex<String,Dictionary>>}
#[test]
fn original_builtin_seed_producer_preserves_exact_value_alias_and_closes_every_birth(){let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();for row in fixture["cases"].as_array().unwrap(){for copy in [1,3,64]{for cancel_at in [None,Some(0),Some(9),Some(37),Some(101)]{let(mut sources,born,free)=observe(||Sources{tree:decode(&row["tree"].to_string()),expected:row["expected"].as_object().unwrap().iter().map(|(key,value)|(key.clone(),decode(&value.to_string()))).collect(),output:None});let original=born-free;let pointer=sources.tree.neurons[0].params.entry_at_rank(0).unwrap().1 as *const NeuralValue;let source=sources.tree.neurons.as_ptr();let(mut cursor,born,free)=observe(FlowEvaluationSeeds::new);assert_eq!((born,free),(0,0));let mut births=0;let mut releases=0;let mut idle=0;for turn in 0..1000000{if cancel_at==Some(turn){break}let demand=cursor.next_demands(&sources.tree,copy).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth};for _ in 0..2{let(result,born,free)=observe(||cursor.step(&sources.tree,RetainedCloneGrant{maximum_items:0,..grant}).unwrap());assert!(result.is_none());assert_eq!(cursor.step_progress(),Default::default());assert_eq!((born,free),(0,0));}let(result,born,free)=observe(||cursor.step(&sources.tree,grant).unwrap());assert!(cursor.step_progress().fits(grant));assert_eq!((born,free),(cursor.step_progress().retained_capacity_bytes,cursor.step_progress().released_bytes));births+=born;releases+=free;assert_eq!(sources.tree.neurons.as_ptr(),source);if let Some(output)=result{sources.output=Some(output);break}if cursor.step_progress()==RetainedCloneProgress::default(){idle+=1}else{idle=0}assert!(idle<64,"original builtin seed stalled phase={} demand={demand:?}",cursor.phase);}if cancel_at.is_none(){assert_eq!(sources.output.as_ref().unwrap(),&sources.expected);let kind=match sources.tree.neurons[0].kind.as_str(){"core.number"=>"number","core.text"=>"text",_=>"image"};let key=if kind=="image"{"dataUrl"}else{"value"};let seed=sources.output.as_ref().unwrap().get(&sources.tree.neurons[0].id).unwrap().get(kind).unwrap().as_dictionary().unwrap();assert_eq!(seed.get(key).unwrap()as *const NeuralValue,pointer);}
 cursor.begin_close();for _ in 0..1000000{if cursor.terminal_is_empty(){break}let demand=cursor.next_close_demands(copy).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth};let(step,born,free)=observe(||cursor.close_step(grant).unwrap());assert!(step.progress().fits(grant));assert_eq!((born,free),(step.progress().retained_capacity_bytes,step.progress().released_bytes));births+=born;releases+=free;}assert!(cursor.terminal_is_empty());let(_,born,free)=observe(||drop(cursor));assert_eq!((born,free),(0,0));let(mut owner,born,free)=observe(||ControlledRetirement::new(sources).unwrap_or_else(|_|unreachable!()));assert_eq!((born,free),(0,0));for _ in 0..1000000{if owner.terminal_is_empty(){break}let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:owner.next_capacity_byte_demand(copy).unwrap(),maximum_release_bytes:owner.next_release_byte_demand().unwrap(),maximum_depth:owner.next_depth_demand().unwrap()};let(step,born,free)=observe(||owner.step(grant).unwrap());assert!(step.progress().fits(grant));assert_eq!((born,free),(step.progress().retained_capacity_bytes,step.progress().released_bytes));births+=born;releases+=free;}assert!(owner.terminal_is_empty());assert_eq!(original+births,releases);let(_,born,free)=observe(||drop(owner));assert_eq!((born,free),(0,0));eprintln!("[DEBUG] Original builtin seed id={} copy={copy} cancel={cancel_at:?} original={original} born={births} release={releases} terminalDrop=0",row["id"]);}}}}
